referenceSolution.python:
def most_gifts(gifts):
    take, skip = 0, 0
    for g in gifts:
        take, skip = skip + g, max(take, skip)
    return max(take, skip)

referenceSolution.javascript:
function most_gifts(gifts) {
  let take = 0;
  let skip = 0;
  for (const g of gifts) [take, skip] = [skip + g, Math.max(take, skip)];
  return Math.max(take, skip);
}

